/**
 * Validate and sanitize episode JSON
 */
function validateAndCleanEpisode(rawJson, topic = '') {
  try {
    let data;
    if (typeof rawJson === 'string') {
      let clean = rawJson.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/<think>[\s\S]*/gi, '');
      clean = clean.replace(/```json/gi, '').replace(/```/g, '').trim();
      const firstBrace = clean.indexOf('{');
      const lastBrace = clean.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
        clean = clean.substring(firstBrace, lastBrace + 1);
      }
      data = JSON.parse(clean);
    } else {
      data = rawJson;
    }

    if (!data || !data.title || !Array.isArray(data.scenes) || data.scenes.length === 0) {
      return null;
    }

    const validActions = [
      'idle', 'talking', 'walking', 'walk_in', 'point_right', 'point_left',
      'thinking', 'sitting', 'confused', 'surprised', 'surprise', 'questioning_users',
      'explain_both', 'comparing', 'laughing', 'excitement', 'looking_left', 'looking_right',
      'akimbo_jaw', 'point_up_left', 'point_up_right'
    ];
    const validEmotions = [
      'neutral', 'happy', 'surprised', 'curious', 'excited', 'thinking', 'concerned', 'laughing'
    ];
    const validCameras = [
      'wide', 'medium', 'close_up', 'medium_to_close', 'pan_left', 'pan_right'
    ];

    const cleanScenes = data.scenes.map((s, idx) => {
      let action = String(s.character_action || 'talking').toLowerCase();
      if (!validActions.includes(action)) action = 'talking';
      
      const pos = String(s.character_position || (idx % 2 === 0 ? 'left' : 'center')).toLowerCase();
      const character_position = ['left', 'center', 'right'].includes(pos) ? pos : 'left';

      const look = String(s.look_target || (action.includes('point') ? 'board' : 'audience')).toLowerCase();
      const look_target = ['audience', 'board', 'board_left', 'thinking'].includes(look) ? look : 'audience';

      return {
        scene: Number(s.scene || idx + 1),
        duration: Math.max(4.0, Math.min(10.0, Number(s.duration || 6.5))),
        dialogue: String(s.dialogue || '').trim(),
        character_action: action,
        character_position,
        look_target,
        emotion: validEmotions.includes(s.emotion) ? s.emotion : 'curious',
        camera: validCameras.includes(s.camera) ? s.camera : 'medium',
        middle_scene_type: s.middle_scene_type || (idx === 0 ? 'intro_hook' : idx === data.scenes.length - 1 ? 'outro_loop' : 'board_schematic'),
        objects: Array.isArray(s.objects) ? s.objects.map(String) : ['prop'],
        background_style: String(s.background_style || data.classroom_style || 'cyber_stem'),
        effects: Array.isArray(s.effects) ? s.effects.map(String) : ['glow'],
        glossary_term: s.glossary_term ? String(s.glossary_term).trim() : null,
        glossary_explanation: s.glossary_explanation ? String(s.glossary_explanation).trim() : null
      };
    }).filter(s => s.dialogue.length > 5);

    if (cleanScenes.length === 0) return null;

    // USER MANDATE: Above a minute (> 60.0 seconds total duration, NO hard cap for maximum)
    let totalDuration = cleanScenes.reduce((sum, sc) => sum + sc.duration, 0);
    if (totalDuration < 60.0) {
      const targetSec = Math.max(65.0, cleanScenes.length * 8.2);
      const ratio = targetSec / (totalDuration || 1);
      cleanScenes.forEach(sc => {
        sc.duration = Math.max(6.0, Math.round(sc.duration * ratio * 10) / 10);
      });
      totalDuration = cleanScenes.reduce((sum, sc) => sum + sc.duration, 0);
      if (totalDuration < 60.5) {
        cleanScenes[cleanScenes.length - 1].duration += Number((61.0 - totalDuration).toFixed(1));
        totalDuration = 61.0;
      }
    }

    // USER MANDATE: Every middle scene must be different!
    // Middle scenes are indices 1 through cleanScenes.length - 2
    if (cleanScenes.length >= 3) {
      const middleActionPool = ['point_right', 'thinking', 'explain_both', 'akimbo_jaw', 'comparing', 'questioning_users', 'point_left'];
      const middleTypePool = ['board_schematic', 'specimen_cutaway', 'comparison_contrast', 'glossary_takeaway'];
      const cameraPool = ['medium_to_close', 'close_up', 'wide', 'medium', 'pan_right'];
      const usedActions = new Set([cleanScenes[0].character_action]);

      for (let i = 1; i < cleanScenes.length - 1; i++) {
        const sc = cleanScenes[i];
        const midIdx = i - 1;

        // 1. Ensure action is distinct from all other scenes
        if (usedActions.has(sc.character_action) || sc.character_action === 'walk_in' || sc.character_action === 'talking' || sc.character_action === 'idle') {
          const freshAction = middleActionPool.find(a => !usedActions.has(a)) || middleActionPool[midIdx % middleActionPool.length];
          sc.character_action = freshAction;
        }
        usedActions.add(sc.character_action);

        // 2. Assign distinct middle scene type
        sc.middle_scene_type = middleTypePool[midIdx % middleTypePool.length];

        // 3. Ensure camera angle does not repeat adjacent scene
        const prevCam = cleanScenes[i - 1].camera;
        if (sc.camera === prevCam) {
          sc.camera = cameraPool.find(c => c !== prevCam) || 'wide';
        }

        // 4. Align look target with action
        if (sc.character_action.includes('point_right')) {
          sc.look_target = 'board';
        } else if (sc.character_action.includes('point_left')) {
          sc.look_target = 'board_left';
        } else if (sc.character_action === 'thinking') {
          sc.look_target = 'thinking';
        } else {
          sc.look_target = 'audience';
        }

        // 5. Ensure glossary term exists if type is glossary_takeaway
        if (sc.middle_scene_type === 'glossary_takeaway' && !sc.glossary_term) {
          const firstHardWord = Array.isArray(data.hard_words) && data.hard_words[0];
          sc.glossary_term = firstHardWord ? firstHardWord.word : (topic.split(/\s+/).slice(0, 2).join(' ') || 'Key Principle');
          sc.glossary_explanation = firstHardWord ? firstHardWord.definition : 'The observable scientific law governing this phenomenon.';
        }
      }
    }

    return {
      topic: String(data.topic || topic).trim(),
      title: String(data.title).replace(/["']/g, '').trim(),
      character_name: String(data.character_name || DEFAULT_CHARACTER),
      target_duration_seconds: Math.round(totalDuration),
      category: data.category || 'science',
      classroom_style: data.classroom_style || 'cyber_stem',
      wiki_search_term: data.wiki_search_term || String(data.title || topic).slice(0, 30),
      scenes: cleanScenes
    };
  } catch (err) {
    console.warn('[Planner Validation Error]:', err.message);
    return null;
  }
}

/**
 * 1. Google Gemini Inference Call (Modern non-decommissioned active models only)
 */
async function callGemini(topic) {
  if (!GEMINI_API_KEY) throw new Error('GEMINI_API_KEY not configured');

  // Strictly active Gemini 2.5-flash (decommissioned 2.0-flash, 2.0-flash-lite, 1.5-flash, 2.5-pro removed)
  const models = ['gemini-2.5-flash'];

  for (const model of models) {
    try {
      console.log(`[AI Planner] Requesting Google Gemini (${model}) for topic: "${topic}"...`);
      const body = JSON.stringify({
        contents: [{
          parts: [{
            text: `${SYSTEM_PROMPT}\n\nTask: Create a fresh educational cartoon episode scene plan (above 60s total duration, 7-9 scenes) for: "${topic}". Return strictly raw JSON matching the schema.`
          }]
        }],
        generationConfig: {
          temperature: 0.7,
          maxOutputTokens: 3000,
          responseMimeType: "application/json"
        }
      });

      const raw = await new Promise((resolve, reject) => {
        const req = https.request(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${GEMINI_API_KEY}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Content-Length': Buffer.byteLength(body)
          },
          timeout: 8000
        }, (res) => {
          let data = '';
          res.on('data', c => data += c);
          res.on('end', () => {
            if (res.statusCode >= 200 && res.statusCode < 300) {
              try {
                const parsed = JSON.parse(data);
                const text = parsed.candidates?.[0]?.content?.parts?.[0]?.text || '';
                resolve(text);
              } catch (e) {
                reject(e);
              }
            } else if (res.statusCode === 429 || res.statusCode === 403) {
              reject(new Error(`Gemini rate limit or access denied (${res.statusCode}). Rolling to next provider immediately.`));
            } else {
              reject(new Error(`Gemini HTTP ${res.statusCode}: ${data.slice(0, 150)}`));
            }
          });
        });
        req.on('error', reject);
        req.on('timeout', () => { req.destroy(); reject(new Error('Gemini request timed out (8s)')); });
        req.write(body);
        req.end();
      });

      const cleaned = validateAndCleanEpisode(raw, topic);
      if (cleaned) {
        return { plan: cleaned, provider: `google/${model}` };
      }
    } catch (e) {
      console.warn(`[AI Planner] Gemini ${model} notice:`, e.message);
      break; // Quota or auth exhausted for key; roll immediately to next provider
    }
  }
  throw new Error('All Gemini models failed or rate-limited');
}

/**
 * 2. Groq Inference Call with Dynamic Auto-Model Discovery
 */
async function callGroq(topic) {
  if (!GROQ_API_KEY) throw new Error('GROQ_API_KEY not configured');

  // Decommissioned models (mixtral-8x7b-32768, llama3-70b-8192) deleted
  let models = [
    'llama-3.3-70b-versatile',
    'llama-3.1-8b-instant',
    'qwen-2.5-32b',
    'deepseek-r1-distill-llama-70b',
    'gemma2-9b-it'
  ];

  let formatGrPayload = null;
  let cleanGrJson = null;
  try {
    const grFinder = require('./groq_model_finder.cjs');
    const verified = await grFinder.fetchAndVerifyGroqModels();
    if (verified && verified.length > 0) {
      models = [...new Set([...verified, ...models])];
      console.log(`[AI Planner] 🔍 Groq Auto-Model Finder activated. Discovered ${verified.length} candidate models: ${models.slice(0, 4).join(', ')}`);
    }
    formatGrPayload = grFinder.formatGroqPayload;
    cleanGrJson = grFinder.cleanGroqJson;
  } catch (mErr) {
    console.warn(`[AI Planner] Groq model finder notice: ${mErr.message}`);
  }

  const userPrompt = `Create an educational cartoon episode scene plan in JSON format for: "${topic}". Ensure the episode is above 60 seconds (7-9 scenes, total duration >=65s). Output strictly valid JSON with root object containing title, description, keywords, and scenes array.`;

  for (const model of models) {
    try {
      console.log(`[AI Planner] Requesting Groq (${model}) for topic: "${topic}"...`);
      const payload = formatGrPayload
        ? formatGrPayload(model, { systemPrompt: SYSTEM_PROMPT, userPrompt, jsonMode: true, maxTokens: 2500 })
        : {
          model,
          messages: [
            { role: 'system', content: SYSTEM_PROMPT },
            { role: 'user', content: userPrompt }
          ],
          temperature: 0.7,
          max_tokens: 2500
        };

      const body = JSON.stringify(payload);

      const raw = await new Promise((resolve, reject) => {
        const req = https.request('https://api.groq.com/openai/v1/chat/completions', {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${GROQ_API_KEY}`,
            'Content-Type': 'application/json',
            'Content-Length': Buffer.byteLength(body)
          },
          timeout: 15000
        }, (res) => {
          let data = '';
          res.on('data', c => data += c);
          res.on('end', () => {
            if (res.statusCode >= 200 && res.statusCode < 300) {
              try {
                const parsed = JSON.parse(data);
                resolve(parsed.choices?.[0]?.message?.content || '');
              } catch (e) {
                reject(e);
              }
            } else {
              reject(new Error(`Groq HTTP ${res.statusCode}: ${data.slice(0, 150)}`));
            }
          });
        });
        req.on('error', reject);
        req.on('timeout', () => { req.destroy(); reject(new Error('Groq request timed out (15s)')); });
        req.write(body);
        req.end();
      });

      const cleaned = (cleanGrJson ? cleanGrJson(raw) : null) || validateAndCleanEpisode(raw, topic);
      if (cleaned) {
        return { plan: cleaned, provider: `groq/${model}` };
      }
    } catch (e) {
      console.warn(`[AI Planner] Groq ${model} failed:`, e.message);
    }
  }
  throw new Error('All Groq models failed');
}

